package dev.veltraph.client.observation.nativeinput;
import com.mojang.blaze3d.platform.InputConstants;
import dev.veltraph.client.service.mc.NormalIdleKeyCarrier;
import java.lang.ref.WeakReference;
import java.util.WeakHashMap;
import net.minecraft.client.KeyMapping;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Options;
/** Actual constructor candidates become birth only after the original Options load and normal return. */
public final class NativeKeyBirthProof {
 private static final WeakHashMap<KeyMapping,Candidate> CANDIDATES=new WeakHashMap<>();
 private static final WeakHashMap<KeyMapping,NativeKeyBirthProof> BORN=new WeakHashMap<>();
 private static final WeakHashMap<Options,OptionsLoad> LOADED=new WeakHashMap<>();
 private static final ThreadLocal<OptionsLoad> LOAD=new ThreadLocal<>();private static final ThreadLocal<ConfiguredBinding> REQUEST=new ThreadLocal<>();
 private final WeakReference<KeyMapping> key;private final WeakReference<Options> options;private final WeakReference<Minecraft> client;
 private Object returnedGuiResetOrigin;private final Thread constructorThread;private final Object exact,bindingHistory;private final String binding;private final WeakReference<KeyMapping>[] originalKeys;
 @SuppressWarnings("unchecked") private NativeKeyBirthProof(KeyMapping k,Options o,Minecraft c,Thread t,Object x,Object h,String b,KeyMapping[] all){key=new WeakReference<>(k);options=new WeakReference<>(o);client=new WeakReference<>(c);constructorThread=t;exact=x;bindingHistory=h;binding=b;originalKeys=(WeakReference<KeyMapping>[])new WeakReference<?>[9];for(int i=0;i<9;i++)originalKeys[i]=new WeakReference<>(all[i]);}
 private boolean originalRoles(Options o){var all=keys(o);if(!unique(all))return false;for(int i=0;i<9;i++)if(originalKeys[i].get()!=all[i])return false;return true;}
 private KeyMapping[] originals(){var all=new KeyMapping[9];for(int i=0;i<9;i++)all[i]=originalKeys[i].get();return all;}
 private static KeyMapping[] keys(Options o){return new KeyMapping[]{o.keyUp,o.keyDown,o.keyLeft,o.keyRight,o.keyJump,o.keyShift,o.keySprint,o.keyAttack,o.keyUse};}
 private static boolean unique(KeyMapping[] all){if(all.length!=9)return false;for(int i=0;i<9;i++){if(all[i]==null)return false;for(int j=0;j<i;j++)if(all[i]==all[j])return false;}return true;}
 private static boolean caller(Class<?> type,String suffix){return StackWalker.getInstance(StackWalker.Option.RETAIN_CLASS_REFERENCE).walk(s->s.limit(16).anyMatch(f->f.getDeclaringClass()==type&&f.getMethodName().endsWith(suffix)));}
 private static boolean constructing(){return caller(Options.class,"<init>")&&caller(Minecraft.class,"<init>");}
 private static final class Candidate {final WeakReference<KeyMapping> key;final Thread thread;final Object exact;Object history;String binding;boolean invalid;Candidate(KeyMapping k,Object x,Object h){key=new WeakReference<>(k);thread=Thread.currentThread();exact=x;history=h;binding=k.saveString();}boolean current(KeyMapping k){return !invalid&&thread==Thread.currentThread()&&key.get()==k&&!k.isDown()&&k instanceof NormalIdleKeyCarrier c&&c.normalIdleKeyCurrent(exact)&&NativeKeyBindingHistory.current(k,history)&&binding.equals(k.saveString());}}
 public boolean current(KeyMapping actual){var o=options.get();var c=client.get();if(o==null||c==null||c.options!=o||constructorThread!=Thread.currentThread()||key.get()!=actual||actual.isDown()||!binding.equals(actual.saveString())||!NativeKeyBindingHistory.current(actual,bindingHistory)||!(actual instanceof NormalIdleKeyCarrier carrier)||!carrier.normalIdleKeyCurrent(exact))return false;return originalRoles(o);}
 public Object keySnapshot(KeyMapping actual){return current(actual)?exact:null;}
 public Object bindingSnapshot(KeyMapping actual){return current(actual)?bindingHistory:null;}
 public String binding(KeyMapping actual){return current(actual)?binding:null;}
 public boolean held(KeyMapping actual){if(!current(actual))throw new IllegalStateException("Constructor lineage unavailable");return false;}
 public static void nativeConstructorReturned(KeyMapping actual){try{if(!caller(KeyMapping.class,"veltraph$manualKeyBorn")||!constructing()||actual.isDown()||!(actual instanceof NormalIdleKeyCarrier carrier)||CANDIDATES.containsKey(actual))return;NativeKeyBindingHistory.constructorReturned(actual);Object history=NativeKeyBindingHistory.snapshot(actual),exact=carrier.normalIdleKeySnapshot();if(history!=null&&exact!=null&&initialNoMutation(exact)&&carrier.normalIdleKeyCurrent(exact))CANDIDATES.put(actual,new Candidate(actual,exact,history));}catch(RuntimeException|Error unavailable){/* Constructor effects and exceptions remain vanilla. */}}
 private static boolean initialNoMutation(Object exact){try{if(exact.getClass()!=dev.veltraph.client.rotation.NormalIdleInputVersion.Snapshot.class)return false;var revision=exact.getClass().getDeclaredField("revision");revision.setAccessible(true);var event=exact.getClass().getDeclaredField("event");event.setAccessible(true);var ordinary=exact.getClass().getDeclaredField("ordinaryEvent");ordinary.setAccessible(true);return revision.getLong(exact)==0&&event.get(exact)==null&&ordinary.get(exact)==null;}catch(ReflectiveOperationException|RuntimeException unavailable){return false;}}
 public static final class OptionsLoad {final WeakReference<Options> options;final WeakReference<Minecraft> client;final Thread thread=Thread.currentThread();final KeyMapping[] keys;final Candidate[] candidates=new Candidate[9];final OptionsLoad prior;boolean invalid,normal;private OptionsLoad(Options o,Minecraft c,OptionsLoad previous){options=new WeakReference<>(o);client=new WeakReference<>(c);keys=keys(o);prior=previous;invalid=previous!=null||!unique(keys);for(int i=0;i<9;i++){candidates[i]=CANDIDATES.get(keys[i]);if(candidates[i]==null||!candidates[i].current(keys[i]))invalid=true;}}boolean header(){var o=options.get();if(o==null||client.get()==null||thread!=Thread.currentThread())return false;var all=keys(o);for(int i=0;i<9;i++)if(keys[i]!=all[i])return false;return true;}}
 public static OptionsLoad beginOptionsLoad(Options o,Minecraft c){try{if(!caller(Options.class,"veltraph$manualConstructorLoad")||!constructing()||o==null||c==null)return null;var prior=LOAD.get();if(prior!=null)prior.invalid=true;var result=new OptionsLoad(o,c,prior);LOAD.set(result);return result;}catch(RuntimeException|Error unavailable){return null;}}
 public static void finishOptionsLoad(OptionsLoad actual,boolean normal){if(actual==null)return;try{if(!caller(Options.class,"veltraph$manualConstructorLoad")||LOAD.get()!=actual||actual.invalid||!normal||!actual.header())return;for(int i=0;i<9;i++)if(!actual.candidates[i].current(actual.keys[i]))return;actual.normal=true;LOADED.put(actual.options.get(),actual);}catch(RuntimeException|Error unavailable){}finally{if(LOAD.get()==actual)LOAD.set(actual.prior);}}
 public static void nativeOptionsConstructorReturned(Options o,Minecraft c){try{if(!caller(Options.class,"veltraph$manualOptionsBorn")||!constructing())return;var actual=LOADED.remove(o);if(actual==null||!actual.normal||actual.invalid||actual.client.get()!=c||!actual.header())return;for(int i=0;i<9;i++)if(BORN.containsKey(actual.keys[i])||!actual.candidates[i].current(actual.keys[i]))return;for(int i=0;i<9;i++){var k=actual.keys[i];var candidate=actual.candidates[i];BORN.put(k,new NativeKeyBirthProof(k,o,c,candidate.thread,candidate.exact,candidate.history,candidate.binding,actual.keys));}}catch(RuntimeException|Error unavailable){/* No birth from a failed or unknown constructor. */}}
 public static final class ConfiguredBinding {final OptionsLoad load;final KeyMapping key;final InputConstants.Key value;final Candidate candidate;final Object before;final ConfiguredBinding prior;boolean claimed,fieldNormal,invalid;Object after;private ConfiguredBinding(OptionsLoad l,KeyMapping k,InputConstants.Key v,Candidate c,ConfiguredBinding p){load=l;key=k;value=v;candidate=c;before=c.history;prior=p;}}
 public static ConfiguredBinding beginConfiguredBinding(Options o,KeyMapping k,InputConstants.Key value){try{var load=LOAD.get();if(!caller(Options.class,"veltraph$manualConfiguredBinding")||load==null||load.invalid||load.options.get()!=o||!load.header()||!caller(Options.class,"load")||!constructing())return null;Candidate c=null;for(int i=0;i<9;i++)if(load.keys[i]==k)c=load.candidates[i];if(c==null||!c.current(k))return null;var prior=REQUEST.get();if(prior!=null){prior.invalid=true;load.invalid=true;return null;}var result=new ConfiguredBinding(load,k,value,c,prior);REQUEST.set(result);return result;}catch(RuntimeException|Error unavailable){return null;}}
 static ConfiguredBinding claimConfiguredField(KeyMapping k,InputConstants.Key value,Object before){var r=REQUEST.get();if(r==null)return null;try{if(r.invalid||r.claimed||r.key!=k||r.value!=value||r.before!=before||LOAD.get()!=r.load||r.load.invalid||!r.load.header()){r.invalid=true;r.load.invalid=true;return null;}r.claimed=true;return r;}catch(RuntimeException|Error unavailable){r.invalid=true;r.load.invalid=true;return null;}}
 static void configuredFieldReturned(ConfiguredBinding r,KeyMapping k,InputConstants.Key value,Object after,boolean normal){if(r==null)return;try{if(REQUEST.get()!=r||r.invalid||!r.claimed||r.key!=k||r.value!=value||r.after!=null||!normal||!NativeKeyBindingHistory.current(k,after)){r.invalid=true;r.load.invalid=true;return;}r.fieldNormal=true;r.after=after;}catch(RuntimeException|Error unavailable){r.invalid=true;r.load.invalid=true;}}
 public static void finishConfiguredBinding(ConfiguredBinding r,boolean normal){if(r==null)return;try{if(!caller(Options.class,"veltraph$manualConfiguredBinding")||REQUEST.get()!=r||r.invalid||!normal||!r.claimed||!r.fieldNormal||r.after==null||LOAD.get()!=r.load||r.load.invalid||!r.load.header()||!(r.key instanceof NormalIdleKeyCarrier c)||!c.normalIdleKeyCurrent(r.candidate.exact)||r.key.isDown()||!NativeKeyBindingHistory.current(r.key,r.after)){r.candidate.invalid=true;r.load.invalid=true;return;}r.candidate.history=r.after;r.candidate.binding=r.key.saveString();}catch(RuntimeException|Error unavailable){r.candidate.invalid=true;r.load.invalid=true;}finally{if(REQUEST.get()==r)REQUEST.set(r.prior);}}
 static void nativeGuiResetReturned(KeyMapping key,NativeGuiKeyResetLineage.NormalReset actual){try{var old=BORN.get(key);if(old==null||actual==null||!NativeKeyBindingHistory.current(key,old.bindingHistory)||!actual.advances(key,old.exact)||!old.binding.equals(actual.binding(key)))return;var after=actual.after(key);var o=old.options.get();var c=old.client.get();if(o==null||c==null||c.options!=o||old.constructorThread!=Thread.currentThread()||!old.originalRoles(o)||after==null||key.isDown()||!(key instanceof NormalIdleKeyCarrier carrier)||!carrier.normalIdleKeyCurrent(after))return;var successor=new NativeKeyBirthProof(key,o,c,old.constructorThread,after,old.bindingHistory,old.binding,old.originals());
  if(resetProducerCaller())successor.returnedGuiResetOrigin=actual.openingOriginIdentity();BORN.put(key,successor);}catch(RuntimeException|Error unavailable){/* Cannot advance unknown binding or before-key history. */}}
 private static boolean resetProducerCaller(){return StackWalker.getInstance(StackWalker.Option.RETAIN_CLASS_REFERENCE).walk(s->s.filter(f->f.getDeclaringClass()!=NativeKeyBirthProof.class).findFirst().map(f->f.getDeclaringClass()==NativeGuiKeyResetLineage.class&&f.getMethodName().equals("finish")).orElse(false));}
 static NativeKeyBirthProof recordedOpeningSuccessor(KeyMapping key,NativeGuiKeyResetLineage.NormalReset reset){
  var proof=BORN.get(key);return proof!=null&&proof.returnedGuiResetOrigin==reset.openingOriginIdentity()&&proof.exact==reset.after(key)&&proof.binding.equals(reset.binding(key))&&proof.current(key)?proof:null;
 }
 boolean retainedOpeningRawCurrent(Object origin,KeyMapping actual,Object history,Object bindingHistory){
  return BORN.get(actual)==this&&returnedGuiResetOrigin==origin&&key.get()==actual&&exact==history&&this.bindingHistory==bindingHistory
   &&dev.veltraph.client.rotation.NormalIdleInputVersion.retainedSnapshotCurrent(history)&&NativeKeyBindingHistory.current(actual,bindingHistory);
 }
 boolean retainedOpeningFields(Object origin,KeyMapping actual,Object history,Object bindingHistory,String binding,Minecraft client,Object options){
  return returnedGuiResetOrigin==origin&&key.get()==actual&&this.exact==history&&this.bindingHistory==bindingHistory&&this.binding.equals(binding)
   &&this.client.get()==client&&this.options.get()==options&&constructorThread==Thread.currentThread()&&current(actual);
 }
 /** Return an already retained actual reset successor only against its original proof; never capture/seed current bits. */
 static NativeKeyBirthProof nativeGuiResetSuccessor(NativeKeyBirthProof before,KeyMapping key,NativeGuiKeyResetLineage.NormalReset actual){try{if(before==null||actual==null||before.key.get()!=key||!NativeKeyBindingHistory.current(key,before.bindingHistory)||!actual.advances(key,before.exact)||!before.binding.equals(actual.binding(key)))return null;var after=BORN.get(key);return after!=null&&after!=before&&after.exact==actual.after(key)&&after.bindingHistory==before.bindingHistory&&after.options.get()==before.options.get()&&after.client.get()==before.client.get()&&after.constructorThread==before.constructorThread&&after.current(key)?after:null;}catch(RuntimeException|Error unavailable){return null;}}
 /** Exact normal GUI close can continue only an existing constructor key proof through its actual declared histories. */
 static NativeKeyBirthProof nativeGuiCloseSuccessor(NativeKeyBirthProof before,KeyMapping key,NativeGuiKeyResetLineage.NormalTransition actual){try{if(before==null||actual==null||actual.nextScreen()!=null||before.key.get()!=key||actual.beforeHeld(key)||actual.held(key)||!actual.current(before.client.get())||!actual.advances(key,before.exact)||!NativeKeyBindingHistory.current(key,before.bindingHistory)||!before.binding.equals(actual.binding(key)))return null;var existing=BORN.get(key);if(existing!=before){return existing!=null&&existing.exact==actual.after(key)&&existing.bindingHistory==before.bindingHistory&&existing.current(key)?existing:null;}var options=before.options.get();var client=before.client.get();var after=actual.after(key);if(options==null||client==null||client.options!=options||before.constructorThread!=Thread.currentThread()||!before.originalRoles(options)||after==null||key.isDown()||!(key instanceof NormalIdleKeyCarrier carrier)||!carrier.normalIdleKeyCurrent(after))return null;var successor=new NativeKeyBirthProof(key,options,client,before.constructorThread,after,before.bindingHistory,before.binding,before.originals());BORN.put(key,successor);return successor;}catch(RuntimeException|Error unavailable){return null;}}
 public static NativeKeyBirthProof peek(KeyMapping actual){try{var result=BORN.get(actual);return result!=null&&result.current(actual)?result:null;}catch(RuntimeException|Error unavailable){return null;}}
}
